def chinese(row):
    key = row.get('parent') or row['id']
    if key.endswith('-s'):
        return NAMES[key[:-2]] + '（侧面）'
    name = NAMES[key]
    if row.get('parent'):
        color = {'black': '黑', 'blonde': '金', 'pink': '粉', 'silver': '银'}[row['id'].rsplit('-', 1)[-1]]
        name += '（' + color + '）'
    return name
